          rawCount: Number(snapshot.rawCount || 0),
          normalizedCount: Number(snapshot.normalizedCount || 0),
          readyCount: Number(snapshot.readyCount || 0),
          uploadingCount: Number(snapshot.uploadingCount || 0),
