        const uploadFile = createTimestampedUploadFile(originalFile);

        item.uploadFile = uploadFile; // \u4ec5\u5f53\u524d\u4e0a\u4f20\u6d41\u7a0b\u4e34\u65f6\u4f7f\u7528\uff0c\u4e0a\u4f20\u5b8c\u6210\u540e\u5fc5\u987b\u6e05\u7406
        item.virtualUploadName = uploadFile.name;
