    function isHardFileReadFailure(reason) {
      const text = String(reason || '');

      return text.includes('\u7f3a\u5c11\u6587\u4ef6\uff0c\u8bf7\u91cd\u65b0\u62d6\u5165') ||
        text.includes('\u6ca1\u6709\u672c\u5730\u6587\u4ef6\u8bfb\u53d6\u6743\u9650') ||
        text.includes('\u672c\u5730\u6587\u4ef6\u8bfb\u53d6\u5931\u8d25') ||
        text.includes('\u672c\u5730\u6587\u4ef6\u4e3a\u7a7a\u6216\u8bfb\u53d6\u5931\u8d25') ||
        text.includes('\u7f3a\u5c11\u53ef\u8bfb\u53d6\u7684\u6587\u4ef6\u5bf9\u8c61') ||
        text.includes('\u8bf7\u91cd\u65b0\u62d6\u5165') ||
        text.includes('\u6ca1\u6709\u53ef\u4e0a\u4f20\u7684 File \u5bf9\u8c61');
    }

    function normalizeUploadComparableFileName(value) {
      if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.normalizeUploadComparableFileName === 'function'
      ) {
        return ComposerApi.normalizeUploadComparableFileName(value);
      }
      let text = String(value || '').trim();
      if (!text) {
        return '';
      }
      if (text.includes('|')) {
        text = text.split('|')[0].trim();
      }
      text = text.replace(/\\/g, '/');
      const parts = text.split('/').filter(Boolean);
      if (parts.length > 0) {
        text = parts[parts.length - 1].trim();
      }
      text = text.replace(/^["'\u201c\u201d\u2018\u2019]+|["'\u201c\u201d\u2018\u2019]+$/g, '').trim();
      text = text
        .replace(/\s+\u538b\u7f29\u5f52\u6863$/i, '')
        .replace(/\s+compressed archive$/i, '')
        .trim();
      return text;
    }

    function normalizeUploadComparableFileStem(value) {
      if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.normalizeUploadComparableFileStem === 'function'
      ) {
        return ComposerApi.normalizeUploadComparableFileStem(value);
      }
      const fileName = normalizeUploadComparableFileName(value);
      if (!fileName) {
        return '';
      }
      return fileName.replace(/\.[^.]+$/u, '').trim();
    }

    function isUploadPhaseActivelyRunning(phase) {
      const normalized = String(phase || '').trim().toLowerCase();
      return normalized === 'running'
        || normalized === 'uploading'
        || normalized === 'preparing'
        || normalized === 'attaching'
        || normalized === 'verifying'
        || normalized === 'cancelling';
    }

    function getUploadAttachmentMatchNames(q) {
      if (!q) return [];
      const rawNames = [
        q.originalName,
        q.originalUploadName,
        q.displayName,
        q.canonicalName,
        q.uploadName,
        q.virtualUploadName,
        q.attachedVirtualUploadName,
        q.name,
      ];
      const names = [];
      rawNames.forEach((value) => {
        const normalized = normalizeUploadComparableFileName(value);
        if (!normalized || names.includes(normalized)) {
          return;
        }
        names.push(normalized);
        const stem = normalizeUploadComparableFileStem(normalized);
        if (stem && !names.includes(stem)) {
          names.push(stem);
        }
      });
      return names;
    }

    const UPLOAD_VERIFY_ACCEPT_CACHE_MS = 10000;
    const UPLOAD_VERIFY_CACHE_LOG_MS = 2000;
    const uploadVerifyCacheLogLastAt = Object.create(null);

    function isUploadItemComposerAcceptedCached(q) {
      if (!q || q.uploadReadyAccepted !== true) {
        return false;
      }
      const acceptedAt = Number(q.uploadAcceptedAt) || 0;
      return acceptedAt > 0 && Date.now() - acceptedAt < UPLOAD_VERIFY_ACCEPT_CACHE_MS;
    }

    function markUploadItemComposerAccepted(q, presence = 'composer-attached') {
      if (!q) {
        return;
      }
      q.uploadAcceptedAt = Date.now();
      q.uploadPresence = String(presence || 'composer-attached');
      q.uploadReadyAccepted = true;
      if (q.id && typeof updateItem === 'function') {
        updateItem(q.id, {
          uploadAcceptedAt: q.uploadAcceptedAt,
          uploadPresence: q.uploadPresence,
          uploadReadyAccepted: true,
        });
      }
    }

    function logUploadVerifyCacheHit(fileKey, line) {
      const key = String(fileKey || '-');
      const now = Date.now();
      const lastAt = Number(uploadVerifyCacheLogLastAt[key]) || 0;
      if (now - lastAt < UPLOAD_VERIFY_CACHE_LOG_MS) {
        return;
      }
      uploadVerifyCacheLogLastAt[key] = now;
      if (
        typeof UploadCriticalRuntime !== 'undefined'
        && UploadCriticalRuntime
        && typeof UploadCriticalRuntime.logUploadTagThrottled === 'function'
      ) {
        UploadCriticalRuntime.logUploadTagThrottled(`UPLOAD_VERIFY_CACHE:${key}`, line, UPLOAD_VERIFY_CACHE_LOG_MS);
      } else if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
        ToolboxShell.appendLog(line);
      }
    }

    function composerHasAttachmentEvidenceForItem(q) {
      if (!q || !ComposerApi || typeof ComposerApi.collectAttachmentChipText !== 'function') {
        return false;
      }
      const fileKey = normalizeUploadComparableFileName(q.originalName || q.name || q.id || '-')
        || String(q.originalName || q.name || q.id || '-');
      if (isUploadItemComposerAcceptedCached(q)) {
        logUploadVerifyCacheHit(
          fileKey,
          `[UPLOAD_VERIFY][COMPOSER_ATTACHED_CACHE_HIT] file=${fileKey} action=accept-upload-ready`,
        );
        return true;
      }
      const haystack = ComposerApi.collectAttachmentChipText();
      const names = getUploadAttachmentMatchNames(q);
      const matched = names.some((name) => ComposerApi.fileNameEvidence(name, haystack));
      if (!matched && names.length) {
        const expectedRawName = names[0] || '';
        const expectedName = normalizeUploadComparableFileName(expectedRawName);
        const expectedStem = normalizeUploadComparableFileStem(expectedRawName);
        ToolboxShell.appendLog(
          `[UPLOAD_VERIFY][FILENAME_MISMATCH] expectedRaw=${String(q.originalName || q.name || '-')} expected=${expectedName || '-'} expectedStem=${expectedStem || '-'} actual=- actualStem=-`,
        );
      }
      if (matched) {
        markUploadItemComposerAccepted(q, 'composer-attached');
      }
      return matched;
    }

    function conversationHistoryHasAttachmentEvidenceForItem(q) {
      if (!q || !ComposerApi || typeof ComposerApi.fileNameEvidence !== 'function') {
        return false;
      }
      const names = getUploadAttachmentMatchNames(q);
      if (!names.length) {
        return false;
      }
      const turns = document.querySelectorAll(
        'article[data-testid^="conversation-turn-"], [data-testid^="conversation-turn-"]',
      );
      if (!turns.length) {
        return false;
      }
      const haystack = Array.from(turns)
        .map((turn) => String(turn.innerText || turn.textContent || '').trim())
        .filter(Boolean)
        .join('\n');
      if (!haystack) {
        return false;
      }
      return names.some((name) => ComposerApi.fileNameEvidence(name, haystack));
    }

    function isUploadItemLocalBound(q) {
      if (!q || isUploadItemLocallyUnreadable(q)) {
        return false;
      }
      const normalizedItem = normalizeUploadItem(q, {
        groupId: getUploadItemGroupId(q) || state.activeGroupId,
      });
      return !!(
        normalizedItem.attachState === UploadState.ATTACHED
        || normalizedItem.composerPresence === 'local-bound'
        || normalizedItem.composerPresence === 'composer-attached'
        || normalizedItem.sendState === 'sent'
        || isQueueItemAlreadyUploaded(q)
        || isLegacyUploadItemAttached(q)
        || hasLocalReadableHandle(q)
      );
    }

    function resolveUploadAttachmentPresenceLevel(q) {
      if (!q) {
        return 'unbound';
      }
      if (isUploadItemComposerAcceptedCached(q)) {
        return 'composer-attached';
      }
      if (composerHasAttachmentEvidenceForItem(q)) {
        return 'composer-attached';
      }
      if (conversationHistoryHasAttachmentEvidenceForItem(q)) {
        return 'conversation-sent';
      }
      if (isUploadItemLocalBound(q)) {
        return 'local-bound';
      }
      return 'unbound';
    }

    function summarizeUploadAttachmentPresenceForScope(scopeGroupId = '') {
      const inScope = (item) => item && isUploadItemInActiveScope(item, scopeGroupId);
      const scopedItems = (state.queue || []).filter(inScope)
        .concat((state.flaskFiles || []).filter(inScope))
        .map((item) => normalizeUploadItem(item, {
          groupId: scopeGroupId || getUploadItemGroupId(item) || state.activeGroupId,
        }));
      const summary = {
        localBound: 0,
        composerAttached: 0,
        conversationSent: 0,
      };
      scopedItems.forEach((item) => {
        const level = resolveUploadAttachmentPresenceLevel(item);
        if (level === 'local-bound') {
          summary.localBound += 1;
        } else if (level === 'composer-attached') {
          summary.composerAttached += 1;
        } else if (level === 'conversation-sent') {
          summary.conversationSent += 1;
        }
      });
      ToolboxShell.appendLog(
        `[UPLOAD][PRESENCE] groupId=${scopeGroupId || state.activeGroupId || '-'} local-bound=${summary.localBound} composer-attached=${summary.composerAttached} conversation-sent=${summary.conversationSent}`,
      );
      return summary;
    }

    function hasAttachmentEvidenceForItem(q) {
      if (!q) return false;

      const names = getUploadAttachmentMatchNames(q);
      const matched = composerHasAttachmentEvidenceForItem(q);
      const presence = resolveUploadAttachmentPresenceLevel(q);
      const canonical = typeof ComposerApi.canonicalFileName === 'function'
        ? ComposerApi.canonicalFileName(q.originalName || q.name || '')
        : '';
      const composerReady = presence === 'composer-attached' ? 1 : 0;
      const conversationMatched = presence === 'conversation-sent' ? 1 : 0;
      const reallyAttached = matched && (composerReady || conversationMatched);
      const matchLine = `[UPLOAD][MATCH] original=${q.originalName || q.name || '-'} display=${q.displayName || q.name || '-'} canonical=${canonical || q.canonicalName || '-'} matched=${reallyAttached ? 1 : 0} presence=${presence} composer=${composerReady} conversation=${conversationMatched} local-bound=${presence === 'local-bound' ? 1 : 0}`;
      const verifyLine = `[UPLOAD_VERIFY][COMPOSER_ATTACHED_OK] file=${q.originalName || q.name || '-'} composer=1 conversation=0 localBound=0 action=accept-upload-ready`;
      const fileKey = String(q.originalName || q.name || q.id || '-');
      if (isUploadItemComposerAcceptedCached(q) && presence === 'composer-attached') {
        logUploadVerifyCacheHit(
          fileKey,
          `[UPLOAD_VERIFY][COMPOSER_ATTACHED_CACHE_HIT] file=${fileKey} action=accept-upload-ready`,
        );
        return reallyAttached;
      }
      if (presence === 'local-bound' && !reallyAttached) {
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[UPLOAD][MATCH_REJECT_LOCAL_BOUND] original=${q.originalName || q.name || '-'} presence=${presence}`,
          );
        }
        return false;
      }
      if (
        typeof UploadCriticalRuntime !== 'undefined'
        && UploadCriticalRuntime
        && typeof UploadCriticalRuntime.isUploadInProgress === 'function'
        && UploadCriticalRuntime.isUploadInProgress()
        && typeof UploadCriticalRuntime.logUploadTagThrottled === 'function'
      ) {
        UploadCriticalRuntime.logUploadTagThrottled(`UPLOAD_MATCH:${fileKey}`, matchLine, 1000);
        if (presence === 'composer-attached') {
          UploadCriticalRuntime.logUploadTagThrottled(`UPLOAD_VERIFY:${fileKey}`, verifyLine, 1000);
          UploadCriticalRuntime.bumpUploadPerfCounter('verifyCount');
        }
      } else {
        ToolboxShell.appendLog(matchLine);
        if (presence === 'composer-attached' && reallyAttached) {
          ToolboxShell.appendLog(verifyLine);
        }
      }
      return reallyAttached;
    }

    async function reconcileFailedItems() {
      const candidates = state.queue.filter((q) => q.state === UploadState.FAILED);

      for (const q of candidates) {
        if (hasAttachmentEvidenceForItem(q)) {
          updateItem(q.id, {
            state: UploadState.ATTACHED,
            message: '',
          });

          ToolboxShell.appendLog(`\u5931\u8d25\u6761\u76ee\u5df2\u590d\u6838\u4e3a\u6210\u529f\uff1a${q.name}`);
        }
      }
    }


