      setStatus('\u672c\u5730\u6587\u4ef6\u5185\u5bb9\u5df2\u5931\u6548\uff0c\u8bf7\u91cd\u65b0\u9009\u62e9\u6587\u4ef6\u540e\u518d\u4e0a\u4f20', 'error');
