              ToolboxShell.appendLog(
                `[AUTOQ][TASK_DONE][FAILED] source=copy-hotkey-continue task=${task.title || '-'} reason=${errText}`,
              );
              failCurrentTask(errText || 'done-signal-handler-failed');
